import re

def parse_json(json_str):
    # Function to parse JSON string
    def parse_value(value):
        value = value.strip()
        if value == 'true':
            return True
        elif value == 'false':
            return False
        elif value == 'null':
            return None
        elif re.match(r'^-?\d+(\.\d+)?$', value):
            return float(value) if '.' in value else int(value)
        elif value.startswith('"') and value.endswith('"'):
            return value[1:-1].replace('\\"', '"').replace('\\\\', '\\')
        elif value.startswith('['):
            return parse_array(value)
        elif value.startswith('{'):
            return parse_object(value)
        else:
            raise ValueError("Invalid JSON value: " + value)

    def parse_array(array_str):
        array_str = array_str.strip()
        if not array_str.startswith('[') or not array_str.endswith(']'):
            raise ValueError("Invalid JSON array: " + array_str)
        elements = array_str[1:-1].split(',')
        return [parse_value(e.strip()) for e in elements]

    def parse_object(object_str):
        object_str = object_str.strip()
        if not object_str.startswith('{') or not object_str.endswith('}'):
            raise ValueError("Invalid JSON object: " + object_str)
        pairs = object_str[1:-1].split(',')
        return {pair.split(':')[0].strip(): parse_value(pair.split(':')[1].strip()) for pair in pairs}

    # Main parsing logic
    try:
        return parse_value(json_str)
    except Exception as e:
        raise SyntaxError("JSON parsing error: " + str(e))

