        elif value == 'true':
            value, index = True, index + 4
        elif value == 'false':
            value, index = False, index + 5
        elif value == 'null':
            value, index = None, index + 4
        elif value == '"':
            value, index = parse_string(value, json_str, index)
        elif value == '{':
            value, index = parse_object(json_str, index)
        elif value == '[':
            value, index = parse_array(json_str, index)
        else:
            raise SyntaxError(f"Unexpected character at index {index}: {value[0]}")
        return value, index

