            value += json_str[index]
            index += 1
            if index < len(json_str) and (json_str[index] == '+' or json_str[index] == '-'):
                value += json_str[index]
                index += 1
            while index < len(json_str) and json_str[index].isdigit():
                value += json_str[index]
                index += 1
