def parse_json(json_str):
    def parse_value(value):
        if value == 'true':
            return True
        elif value == 'false':
            return False
        elif value == 'null':
            return None
        elif '.' in value:
            return float(value)
        elif value.lstrip('-').isdigit():
            return int(value)
        elif value[0] == '"' and value[-1] == '"':
            return value[1:-1].replace('\\"', '"').replace('\\n', '\n')
        else:
            raise ValueError("Invalid JSON value")

    def parse_array():
        nonlocal json_str
        items = []
        json_str = json_str[1:-1]
        while json_str:
            item, json_str = parse_value(json_str), json_str.strip()
            items.append(item)
            if json_str[0] == ',':
                json_str = json_str[1:].strip()
            elif json_str[0] == ']':
                break
            else:
                raise ValueError("Invalid JSON array")
        return items

    def parse_object():
        nonlocal json_str
        items = {}
        json_str = json_str[1:-1]
        while json_str:
            key, json_str = json_str[0:json_str.index(':')], json_str[json_str.index(':') + 1:]
            key = parse_value(key.strip())
            if json_str[0] == '"':
                value, json_str = json_str[1:json_str.index('"')], json_str[json_str.index('"') + 1:]
            else:
                value, json_str = parse_value(json_str), json_str.strip()
            items[key] = value
            if json_str[0] == ',':
                json_str = json_str[1:].strip()
            elif json_str[0] == '}':
                break
            else:
                raise ValueError("Invalid JSON object")
        return items

    json_str = json_str.strip()
    if json_str[0] == '{':
        return parse_object()
    elif json_str[0] == '[':
        return parse_array()
    else:
        return parse_value(json_str)

