import re

def parse_json(json_str):
    def parse_value(value):
        if value.startswith('"') and value.endswith('"'):
            return value[1:-1].replace('\\"', '"').replace('\\n', '\n').replace('\\t', '\t').replace('\\b', '\b').replace('\\f', '\f').replace('\\r', '\r')
        elif value.lower() == 'true':
            return True
        elif value.lower() == 'false':
            return False
        elif value.lower() == 'null':
            return None
        elif value.lstrip('-').isdigit():
            return int(value)
        elif re.match(r'^-?\d+\.\d+$', value):
            return float(value)
        else:
            raise ValueError("Invalid JSON value")

    def parse_object(obj):
        if obj == '{}':
            return {}
        else:
            obj = obj[1:-1]
            pairs = obj.split(',')
            result = {}
            for pair in pairs:
                key, value = pair.split(':')
                result[parse_value(key.strip())] = parse_value(value.strip())
            return result

    def parse_array(arr):
        if arr == '[]':
            return []
        else:
            arr = arr[1:-1]
            elements = [element.strip() for element in arr.split(',')]
            result = []
            for element in elements:
                result.append(parse_value(element))
            return result

    json_str = json_str.strip()
    if json_str[0] == '{':
        return parse_object(json_str)
    elif json_str[0] == '[':
        return parse_array(json_str)
    else:
        return parse_value(json_str)

