        if obj_str == '{}':
            return {}
        obj_str = obj_str[1:-1].strip()
        obj = {}
        pairs = obj_str.split(',')
        for pair in pairs:
            key, value = pair.strip().split(':')
            obj[parse_value(key.strip())] = parse_value(value.strip())
        return obj

    def parse_array(arr_str):
        if arr_str == '[]':
            return []
        arr_str = arr_str[1:-1].strip()
        arr = []
        items = arr_str.split(',')
        for item in items:
            arr.append(parse_value(item.strip()))
        return arr

