            return parse_array(value[1:-1])
        elif value[0] == '{':
            return parse_object(value[1:-1])

    def parse_array(array_str):
        elements = []
        while array_str:
            if array_str[0] == ',':
                array_str = array_str[1:].strip()
                continue
            element, array_str = parse_value(array_str.strip()), array_str.strip()
            elements.append(element)
            if not array_str:
                break
            array_str = array_str[1:].strip()
        return elements

