        elif value == 'false':
            return False
        elif value == 'null':
            return None
        elif re.match(r'^-?\d+(\.\d+)?$', value):
            return float(value) if '.' in value else int(value)
        elif value.startswith('"') and value.endswith('"'):
            return value[1:-1].replace('\\"', '"').replace('\\n', '\n')
        else:
            raise ValueError("Invalid JSON value")

    def parse_object():
        if json_str[pos] != '{':
            raise ValueError("Expected '{'")
        pos += 1
        result = {}
        while json_str[pos] != '}':
            if json_str[pos] == '"':
                key = parse_string()
                pos += 1
                if json_str[pos] != ':':
                    raise ValueError("Expected ':'")
                pos += 1
                value = parse_value(parse_token())
                result[key] = value
                if json_str[pos] == ',':
                    pos += 1
                else:
                    break
            else:
                raise ValueError("Expected string key")
        pos += 1
        return result

    def parse_array():
        if json_str[pos] != '[':
            raise ValueError("Expected '['")
        pos += 1
        result = []
        while json_str[pos] != ']':
            value = parse_value(parse_token())
            result.append(value)
            if json_str[pos] == ',':
                pos += 1
            else:
                break
        pos += 1
        return result

    def parse_string():
        if json_str[pos] != '"':
            raise ValueError("Expected string")
        pos += 1
        start = pos
        while pos < len(json_str) and json_str[pos] != '"':
            pos += 1
        if pos == len(json_str):
            raise ValueError("Unterminated string")
        result = json_str[start:pos]
        pos += 1
        return result

    def parse_token():
        start = pos
        if json_str[pos] == '"':
            return parse_string()
        elif json_str[pos] == '{':
            return parse_object()
        elif json_str[pos] == '[':
            return parse_array()
        elif re.match(r'^-?\d+(\.\d+)?$', json_str[pos:]):
            return parse_value(json_str[start:])
        else:
            raise ValueError("Invalid token")

    pos = 0
    try:
        result = parse_token()
        if pos != len(json_str):
