        value_str = value_str.strip()
        if value_str == 'true':
            return True
        elif value_str == 'false':
            return False
        elif value_str == 'null':
            return None
        elif value_str[0] == '"':
            return value_str[1:-1].replace('\\"', '"')
        elif value_str[0] == '[':
            return parse_array(value_str)
