def parse_json(json_str):
    def parse_value(value):
        if value == 'true':
            return True
        elif value == 'false':
            return False
        elif value == 'null':
            return None
        elif value[0] == '"':
            return value[1:-1].replace('\\"', '"').replace('\\n', '\n')
        elif value[0] == '{':
            return parse_object(value)
        elif value[0] == '[':
            return parse_array(value)
        else:
            try:
                return int(value)
            except ValueError:
                try:
                    return float(value)
                except ValueError:
                    raise ValueError("Invalid JSON value")

    def parse_object(json_str):
        json_str = json_str.strip()[1:-1]
        obj = {}
        while json_str:
            key, value = json_str.split(':')
            key = parse_value(key.strip())
            value = parse_value(value.strip())
            obj[key] = value
            json_str = json_str[len(key) + len(value) + 1:].strip()
            if json_str[0] == ',':
                json_str = json_str[1:].strip()
        return obj

    def parse_array(json_str):
        json_str = json_str.strip()[1:-1]
        arr = []
        while json_str:
            value = json_str.split(',')[0]
            arr.append(parse_value(value.strip()))
            json_str = json_str[len(value) + 1:].strip()
            if json_str[0] == ',':
                json_str = json_str[1:].strip()
        return arr

    try:
        return parse_value(json_str)
    except Exception as e:
        raise SyntaxError("Invalid JSON syntax") from e

